#!/usr/bin/env node
// Embeds the verbatim upstream prompt markdown into src/prompts-data.ts so the text ships inside bundled hosts
// (Electron asar, single-file CLI) without runtime file reads. The generated file is committed; a test checks it is in sync.
import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");

export function buildPromptData() {
  const entries = {};
  const add = (dir, prefix) => {
    for (const file of readdirSync(join(root, dir)).sort()) {
      if (!file.endsWith(".md")) continue;
      entries[`${prefix}${file.slice(0, -3)}`] = readFileSync(join(root, dir, file), "utf8").replace(/\r\n/g, "\n").replace(/\n+$/, "");
    }
  };
  add("prompts", "");
  add("prompts/team", "team/");
  entries["skill/github"] = readFileSync(join(root, "skills/github/SKILL.md"), "utf8").replace(/\r\n/g, "\n").replace(/\n+$/, "");
  return entries;
}

export function render(entries) {
  const body = Object.entries(entries)
    .map(([name, text]) => `  ${JSON.stringify(name)}: ${JSON.stringify(text)},`)
    .join("\n");
  return [
    "// GENERATED by scripts/embed-prompts.mjs from prompts/**/*.md and skills/github/SKILL.md. Do not edit by hand.",
    "// The prompt text is verbatim from github.com/deepseek-ai/dsh-superagent-prototype (MIT); see UPSTREAM-LICENSE.",
    "export const PROMPT_DATA: Readonly<Record<string, string>> = {",
    body,
    "};",
    "",
  ].join("\n");
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  writeFileSync(join(root, "src/prompts-data.ts"), render(buildPromptData()));
}
